payload.json_schema:
{
    "$schema": "http://json-schema.org/draft-04/schema",
    "additionalProperties": false,
    "properties": {
        "homePage": {
            "_format": "uri",
            "description": "the homepage for this career site",
            "type": "string"
        },
        "id": {
            "description": "immutable id for this career site",
            "type": "integer"
        },
        "label": {
            "description": "label for this career site, e.g. Graduate recruitment site",
            "type": "string"
        }
    },
    "required": [
        "id",
        "label",
        "homePage"
    ],
    "type": "object"
}

{
    "additionalProperties": false,
    "properties": {
        "coverLetter": {
            "access": "candidateOwned",
            "description": "Please upload a cover letter. The shorter the better",
            "format": "tas-fileUpload",
            "options": {
                "accept": "image/png,text/html"
            },
            "properties": {
                "data": {
                    "media": {
                        "binaryEncoding": "base64"
                    },
                    "type": "string"
                },
                "fileName": {
                    "type": "string"
                },
                "via": {
                    "type": "string"
                }
            },
            "type": "object"
        },
        "favoriteColor": {
            "access": "eeo",
            "default": "blue",
            "description": "Tell us your favorite color. Our advanced hiring algorithm uses it.",
            "title": "Favorite color",
            "type": "string"
        }
    },
    "required": [
        "favoriteColor"
    ],
    "type": "object"
}

{
    "$schema": "http://json-schema.org/draft-07/schema#",
    "additionalProperties": false,
    "properties": {
        "anonymousRecruitment": {
            "type": "boolean"
        },
        "locations": {
            "items": {
                "enum": [
                    "Scotland",
                    "North East England",
                    "North West England",
                    "Yorkshire and the Humber",
                    "East Midlands",
                    "West Midlands",
                    "East of England",
                    "Wales",
                    "London",
                    "South East England",
                    "South West England",
                    "Northern Ireland",
                    "International (outside the UK)"
                ]
            },
            "maxItems": 13,
            "minItems": 1,
            "type": "array",
            "_uniqueItems": true
        },
        "manageIncentives": {
            "type": "boolean"
        },
        "recruitFromList": {
            "type": "boolean"
        },
        "recruitMethods": {
            "items": {
                "enum": [
                    "Entirely offline",
                    "Initial recruitment offline, but then contact them online",
                    "Entirely online"
                ]
            },
            "maxItems": 3,
            "minItems": 1,
            "type": "array",
            "_uniqueItems": true
        }
    },
    "required": [
        "anonymousRecruitment",
        "locations",
        "manageIncentives",
        "recruitFromList",
        "recruitMethods"
    ],
    "title": "Digital Outcomes and Specialists 4 User research participants Service Schema",
    "type": "object"
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "definitions": {
        "id": {
            "type": "integer"
        }
    },
    "type": "object",
    "properties": {
        "id": {
            "$ref": "#/definitions/id"
        },
        "label": {
            "type": "string"
        },
        "phase": {
            "description": "Buckets have a phase, which represents the approximate part of the recruitment process this bucket is for - for example the phase 'interview' might have several buckets (e.g. 'line manager interview', etc.).",
            "enum": [
                "new",
                "screening",
                "interview",
                "selection",
                "offer",
                "approval",
                "hire",
                "onboard",
                "decline",
                "other"
            ]
        },
        "key": {
            "type": "string"
        }
    },
    "required": [
        "id",
        "label",
        "phase"
    ],
    "additionalProperties": false
}

{
    "$schema": "http://json-schema.org/draft-06/schema#",
    "title": "Generic Job Output",
    "type": "object",
    "properties": {
        "status": {
            "type": "string",
            "enum": [
                "Success",
                "Failure",
                "Timeout"
            ],
            "description": "Result status of the job"
        },
        "message": {
            "type": "string",
            "description": "Should capture a summarized error message in case of Failures."
        },
        "results": {
            "type": "object",
            "description": "JSON object holding the job specific output details"
        }
    },
    "required": [
        "status"
    ]
}

{
    "additionalProperties": false,
    "properties": {
        "educationPricing": {
            "type": "boolean"
        },
        "id": {
            "pattern": "^([0-9]{16})$",
            "type": "string"
        },
        "incidentEscalation": {
            "type": "boolean"
        },
        "lot": {
            "enum": [
                "SCS"
            ]
        },
        "minimumContractPeriod": {
            "enum": [
                "Hour",
                "Day",
                "Month",
                "Year",
                "Other"
            ]
        },
        "priceInterval": {
            "enum": [
                "",
                "Second",
                "Minute",
                "Hour",
                "Day",
                "Week",
                "Month",
                "Quarter",
                "6 months",
                "Year"
            ]
        },
        "priceMax": {
            "type": [
                "number",
                "null"
            ]
        },
        "priceMin": {
            "minimum": 0,
            "type": "number"
        },
        "priceString": {
            "type": "string"
        },
        "priceUnit": {
            "enum": [
                "Unit",
                "Person",
                "Licence",
                "User",
                "Device",
                "Instance",
                "Server",
                "Virtual machine",
                "Transaction",
                "Megabyte",
                "Gigabyte",
                "Terabyte"
            ]
        },
        "pricingDocumentURL": {
            "_format": "uri",
            "type": "string"
        },
        "serviceBenefits": {
            "items": {
                "maxLength": 100,
                "pattern": "^(?:\\S+\\s+){0,9}\\S+$",
                "type": "string"
            },
            "maxItems": 10,
            "minItems": 1,
            "type": "array"
        },
        "serviceDefinitionDocumentURL": {
            "_format": "uri",
            "type": "string"
        },
        "serviceFeatures": {
            "items": {
                "maxLength": 100,
                "pattern": "^(?:\\S+\\s+){0,9}\\S+$",
                "type": "string"
            },
            "maxItems": 10,
            "minItems": 1,
            "type": "array"
        },
        "serviceName": {
            "maxLength": 100,
            "minLength": 1,
            "type": "string"
        },
        "serviceSummary": {
            "maxLength": 500,
            "minLength": 1,
            "pattern": "^(?:\\S+\\s+){0,49}\\S+$",
            "type": "string"
        },
        "serviceTypes": {
            "items": {
                "enum": [
                    "Implementation",
                    "Ongoing support",
                    "Planning",
                    "Testing",
                    "Training"
                ]
            },
            "maxItems": 5,
            "type": "array",
            "_uniqueItems": true
        },
        "sfiaRateDocumentURL": {
            "_format": "uri",
            "type": "string"
        },
        "status": {
            "enum": [
                "disabled",
                "enabled",
                "published",
                "submitted",
                "not-submitted"
            ]
        },
        "supplierId": {
            "type": "integer"
        },
        "supportAvailability": {
            "maxLength": 200,
            "minLength": 1,
            "pattern": "^(?:\\S+\\s+){0,19}\\S+$",
            "type": "string"
        },
        "supportForThirdParties": {
            "type": "boolean"
        },
        "supportResponseTime": {
            "maxLength": 200,
            "minLength": 1,
            "pattern": "^(?:\\S+\\s+){0,19}\\S+$",
            "type": "string"
        },
        "supportTypes": {
            "items": {
                "enum": [
                    "Service desk",
                    "Email",
                    "Phone",
                    "Live chat",
                    "Onsite"
                ]
            },
            "maxItems": 5,
            "minItems": 1,
            "type": "array",
            "_uniqueItems": true
        },
        "terminationCost": {
            "type": "boolean"
        },
        "termsAndConditionsDocumentURL": {
            "_format": "uri",
            "type": "string"
        },
        "vatIncluded": {
            "type": "boolean"
        },
        "vendorCertifications": {
            "items": {
                "maxLength": 100,
                "pattern": "^(?:\\S+\\s+){0,9}\\S+$",
                "type": "string"
            },
            "maxItems": 10,
            "type": "array"
        }
    },
    "required": [
        "id",
        "supplierId",
        "lot",
        "serviceDefinitionDocumentURL",
        "termsAndConditionsDocumentURL",
        "pricingDocumentURL",
        "serviceName",
        "serviceSummary",
        "serviceTypes",
        "serviceFeatures",
        "serviceBenefits",
        "priceMin",
        "priceUnit",
        "priceString",
        "vatIncluded",
        "educationPricing",
        "terminationCost",
        "minimumContractPeriod",
        "supportTypes",
        "supportForThirdParties",
        "supportAvailability",
        "supportResponseTime",
        "incidentEscalation"
    ],
    "title": "G-Cloud 7 SCS Service Schema",
    "type": "object"
}
